/* BALI TOGETHER — GitHub Pages + optional Supabase */
(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const DAY=86400000, STORAGE='bali-together-demo-v2', TRIP_STORAGE='bali-together-current-trip';
const config=window.BALI_CONFIG||{};
const sharedConfigured=!!(config.SUPABASE_URL&&config.SUPABASE_ANON_KEY);
const cloudOn=!!(sharedConfigured&&window.supabase);
const api=cloudOn?window.supabase.createClient(config.SUPABASE_URL,config.SUPABASE_ANON_KEY):null;
const state={mode:sharedConfigured?'shared':'demo',user:null,tripId:null,view:'dashboard',priceFilter:'all',day:'',data:null,channel:null,loginId:'',ready:false};
const labels={dashboard:'OVERVIEW',itinerary:'ITINERARY',members:'CREW',prices:'PRICE TRACKER',expenses:'EXPENSES',settings:'SETTINGS'};
const cats={activity:'액티비티',food:'맛집 / 식사',stay:'숙소',transport:'이동',flight:'항공',todo:'기타'};
const colors=['#c9ebe0','#f8e1cb','#e0e8fa','#f7e8b9','#dcebd5','#eedaf1','#dbe9f2','#f1ddd4'];
const pad=n=>String(n).padStart(2,'0');
const uid=()=>globalThis.crypto?.randomUUID?.()||('id'+Date.now()+Math.random().toString(36).slice(2));
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=E;
const money=n=>'₩'+Math.round(Number(n)||0).toLocaleString('ko-KR');
const dateUTC=v=>new Date(String(v).slice(0,10)+'T12:00:00Z');
const nextDate=(v,n=1)=>{const d=dateUTC(v);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const diff=(a,b)=>Math.round((dateUTC(b)-dateUTC(a))/DAY);
const dates=(a,b)=>{let result=[],limit=Math.min(Math.max(diff(a,b)+1,0),93);for(let i=0;i<limit;i++)result.push(nextDate(a,i));return result};
const dateText=v=>v?new Intl.DateTimeFormat('ko-KR',{timeZone:'UTC',month:'short',day:'numeric',weekday:'short'}).format(dateUTC(v)):'미정';
const monthDay=v=>v?new Intl.DateTimeFormat('ko-KR',{timeZone:'UTC',month:'short',day:'numeric'}).format(dateUTC(v)):'미정';
const dayLabel=v=>v?.split('-').slice(1).join('.')||'--';
const monthName=v=>v?new Intl.DateTimeFormat('en-US',{timeZone:'UTC',month:'short'}).format(dateUTC(v)).toUpperCase():'SEP';
const trim=v=>String(v||'').trim();
const safeUrl=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const arr=v=>Array.isArray(v)?v:[];
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});
function sampleData(){
const trip={id:'demo-trip',title:'Bali, Here We Come!',start_date:'2027-09-01',end_date:'2027-09-21',invite_code:'DEMO-ONLY',owner_id:null,description:'21일간의 특별한 발리 여행'};
const members=[['멤버 1','2027-09-01','2027-09-21'],['멤버 2','2027-09-01','2027-09-21'],['멤버 3','2027-09-01','2027-09-21'],['멤버 4','2027-09-01','2027-09-21'],['멤버 5','2027-09-01','2027-09-21'],['멤버 6','2027-09-01','2027-09-21'],['멤버 7','2027-09-06','2027-09-15'],['멤버 8','2027-09-11','2027-09-19']].map((m,i)=>({id:'m'+(i+1),trip_id:'demo-trip',name:m[0],starts_on:m[1],ends_on:m[2],role:i===0?'organizer':'member',user_id:null}));
const ev=[['2027-09-01','발리 도착 · 체크인','꾸따','transport','공항 픽업과 첫 숙소 체크인'],['2027-09-02','스미냑 해변 산책','스미냑','activity','선셋 보고 저녁 식사'],['2027-09-04','울루와뚜 일정','울루와뚜','activity','절벽 사원과 비치클럽'],['2027-09-06','멤버 7 합류','공항','transport','합류 시간에 맞춰 픽업'],['2027-09-09','우붓 이동','우붓','transport','숙소 이동 · 교통편 미정'],['2027-09-11','멤버 8 합류','우붓','transport','합류 장소 확인'],['2027-09-14','스노클링 후보','누사페니다','activity','날씨와 현장 상황 확인'],['2027-09-20','마지막 쇼핑','꾸따','food','귀국 전 자유 일정']].map((v,i)=>({id:'e'+i,trip_id:trip.id,date:v[0],title:v[1],area:v[2],category:v[3],note:v[4],status:'idea',time:''}));
const watches=[{id:'w1',trip_id:trip.id,kind:'flight',label:'인천 ↔ 발리 직항 (왕복)',provider:'항공사 비교',url:'',origin:'ICN',dest:'DPS',depart_on:'2027-09-01',return_on:'2027-09-21',nonstop:true,adults:1,rooms:1,currency:'KRW',target_price:650000,is_active:true,note:'예시 가격입니다. 실제 조회 결과가 아닙니다.'},{id:'w2',trip_id:trip.id,kind:'stay',label:'스미냑 풀빌라 후보',provider:'숙소 비교',url:'',checkin_on:'2027-09-01',checkout_on:'2027-09-09',amadeus_hotel_id:'',adults:8,rooms:4,currency:'KRW',target_price:1800000,is_active:true,note:'예시 가격입니다. 실제 조회 결과가 아닙니다.'},{id:'w3',trip_id:trip.id,kind:'flight',label:'부분 합류 멤버 항공편',provider:'항공사 비교',url:'',origin:'ICN',dest:'DPS',depart_on:'2027-09-11',return_on:'2027-09-19',nonstop:true,adults:1,rooms:1,currency:'KRW',target_price:600000,is_active:true,note:'예시 가격입니다. 실제 조회 결과가 아닙니다.'}];
const q=[['w1',810000,'2026-11-01'],['w1',764000,'2026-11-06'],['w1',728000,'2026-11-11'],['w2',2150000,'2026-11-01'],['w2',2040000,'2026-11-07'],['w2',1980000,'2026-11-11'],['w3',719000,'2026-11-04'],['w3',689000,'2026-11-11']].map((v,i)=>({id:'q'+i,trip_id:trip.id,watch_id:v[0],price:v[1],currency:'KRW',observed_at:v[2]+'T09:00:00Z',provider:'예시 데이터',summary:'가상 시세 · 실제 판매 가격 아님'}));
return {trip,members,events:ev,watches,quotes:q,expenses:[]};}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__baliToast);window.__baliToast=setTimeout(()=>t.classList.remove('show'),3400)}
function getData(){return state.data||sampleData()}
function memberActive(m,day){return day>=m.starts_on&&day<=m.ends_on}
function present(day){return getData().members.filter(m=>memberActive(m,day))}
function inTrip(day){const t=getData().trip;return !!(t&&day>=t.start_date&&day<=t.end_date)}
function maxDays(){const t=getData().trip;return t?dates(t.start_date,t.end_date):[]}
function isOwner(){return state.mode==='demo'||getData().trip?.owner_id===state.user?.id}
function dateRangeOf(m){return `${dayLabel(m.starts_on)} – ${dayLabel(m.ends_on)}`}
function kindPill(k){return `<span class="pill ${E(k)}">${k==='flight'?'✈ 항공':'⌂ 숙소'}</span>`}
function categoryPill(k){return `<span class="pill ${E(k)}">${E(cats[k]||'기타')}</span>`}
function personAvatar(m,i=0){return `<span class="avatar" style="background:${colors[(i<0?0:i)%colors.length]}">${E((m?.name||'?').slice(0,1))}</span>`}
function getMember(id){return getData().members.find(m=>m.id===id)}
function quotesOf(id){return getData().quotes.filter(q=>q.watch_id===id).sort((a,b)=>String(a.observed_at).localeCompare(String(b.observed_at)))}
function latestPrice(w){return quotesOf(w.id).at(-1)}
function change(w){const q=quotesOf(w.id);return q.length>1?(q.at(-1).price-q.at(-2).price):null}
function header(eyebrow,title,subtitle,buttons=''){return `<div class="page-top"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-sub">${subtitle}</p></div><div class="actions">${buttons}</div></div>`}
const button=(txt,action,cls='btn-primary',id='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${attr(id)}"`:''}>${txt}</button>`;
const quickLink=(text,url)=>safeUrl(url)?`<a class="btn btn-light btn-small" href="${attr(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`:'';
function chart(q){let a=q.slice(-12),w=400,h=100;if(!a.length)return `<svg class="watch-chart" viewBox="0 0 400 100" role="img" aria-label="시세 기록 없음"><text x="200" y="54" text-anchor="middle" fill="#a2b5ac" font-size="12">가격을 기록하면 추이가 표시됩니다</text></svg>`;
let vals=a.map(x=>Number(x.price)),low=Math.min(...vals),high=Math.max(...vals),span=high-low||1;let points=a.map((x,i)=>({x:28+(i*(w-56)/Math.max(a.length-1,1)),y:78-(Number(x.price)-low)/span*54}));let d=points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');let fill=d+` L${points.at(-1).x} 86 L${points[0].x} 86 Z`;return `<svg class="watch-chart" viewBox="0 0 400 100" preserveAspectRatio="none" role="img" aria-label="기록된 가격 ${a.length}건, ${money(vals[0])}부터 ${money(vals.at(-1))}까지"><line x1="20" y1="33" x2="380" y2="33" stroke="#e9f0e9" stroke-dasharray="4,5"/><line x1="20" y1="67" x2="380" y2="67" stroke="#e9f0e9" stroke-dasharray="4,5"/>${a.length>1?`<path d="${fill}" fill="#5db69d1a"/><path d="${d}" fill="none" stroke="#1c9581" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/>`:''}${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${i===a.length-1?'5':'3'}" fill="${i===a.length-1?'#1b8e7b':'#83c7b1'}" stroke="white" stroke-width="1.5"/>`).join('')}</svg>`}
function watchCard(w){const q=latestPrice(w),c=change(w),hit=!!(q&&w.target_price&&q.price<=w.target_price);const qs=quotesOf(w.id);const dt=w.kind==='flight'?`${dayLabel(w.depart_on)} 출국${w.return_on?' · '+dayLabel(w.return_on)+' 귀국':''} · ${w.nonstop?'직항':'경유 포함'}`:`${dayLabel(w.checkin_on)}~${dayLabel(w.checkout_on)} · ${Math.max(0,diff(w.checkin_on,w.checkout_on))}박`;
return `<article class="card watch-card"><div class="watch-top">${kindPill(w.kind)}<div class="actions">${hit?`<span class="pill good">목표가 도달</span>`:''}<button class="btn btn-light btn-small" data-action="editWatch" data-id="${E(w.id)}">수정</button></div></div><h3>${E(w.label)}</h3><div class="watch-description">${E(dt)} · ${E(w.provider||'가격 비교')}</div><div class="watch-values"><div><small>최근 기록가 ${state.mode==='demo'?'· 가상 예시':''}</small><strong>${q?money(q.price):'아직 없음'}</strong></div><div style="text-align:right"><small>목표 가격</small><strong style="font-size:16px;color:#658a7f">${w.target_price?money(w.target_price):'미설정'}</strong><div class="price-change ${c!==null?(c<0?'down':'up'):''}">${c===null?'기록을 추가해 주세요':c===0?'변동 없음':`${c<0?'▼':'▲'} ${money(Math.abs(c))} 전 기록 대비`}</div></div></div>${chart(qs)}<div class="watch-foot"><div class="subtle">${q?'기록: '+dateText(String(q.observed_at).slice(0,10))+' · '+E(q.provider||'직접 입력'):'가격 기록 없음'}${w.kind==='stay'&&w.amadeus_hotel_id?' · API 연동 후보':''}</div><div class="actions">${quickLink('검색',w.url)}${button('+ 가격 기록','addQuote','btn-soft btn-small',w.id)}</div></div><div class="watch-history"><div style="display:flex;justify-content:space-between;align-items:center"><b style="font-size:11px">최근 가격 기록</b><button class="btn-ghost" data-action="toggleHistory" data-id="${E(w.id)}" style="font-size:11px">내역 보기 ▾</button></div><div id="history-${E(w.id)}" class="hidden" style="margin-top:7px">${qs.slice(-8).reverse().map(q=>`<div class="watch-history-row"><span>${dateText(String(q.observed_at).slice(0,10))} · ${E(q.provider||'직접 입력')}</span><span><b>${money(q.price)}</b> <button class="btn-ghost" title="삭제" data-action="deleteQuote" data-id="${E(q.id)}">×</button></span></div>`).join('')||'<p class="help">기록 없음</p>'}</div></div></article>`}
function dashboard(){const d=getData(),t=d.trip,tripdays=maxDays(),upcoming=d.events.filter(e=>e.date>=t.start_date).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5),alerts=d.watches.filter(w=>w.target_price&&latestPrice(w)?.price<=w.target_price);const people=d.members.length,expSum=d.expenses.reduce((s,x)=>s+Number(x.amount),0),full=d.members.filter(m=>m.starts_on===t.start_date&&m.ends_on===t.end_date).length;
return `${header('THE BIG PICTURE','우리의 발리 여행, 한눈에','8명이 함께 계획하고, 각자 다른 날짜도 쉽게 관리해요.',button('+ 일정 추가','addEvent'))}${state.mode==='demo'?'<div class="notice warn" style="margin-bottom:15px">⚠️ 현재 화면은 <b>시연용 예시 여행</b>입니다. 표시된 항공·숙소 금액은 실제 조회 가격이 아닙니다.</div>':''}
<div class="card hero"><div class="hero-inner"><div class="eyebrow" style="color:#90d4bb">✳ THE COUNTDOWN TO PARADISE</div><h2>${E(t.title)}</h2><p>✈ ${E(t.start_date)} — ${E(t.end_date)} &nbsp; · &nbsp; 인천 → 발리</p></div><div class="hero-ill">✺</div><div class="hero-stat"><div><div class="hero-number">${tripdays.length}<small>DAYS</small></div><div class="subtle" style="color:#b1d3cb">전체 여행 일정</div></div><span class="divider-vertical"></span><div><div class="hero-number">${people}<small>CREW</small></div><div class="subtle" style="color:#b1d3cb">함께하는 인원</div></div></div></div>
<div class="stats"><div class="card stat"><div class="stat-head">등록된 멤버 <span class="stat-icon">♧</span></div><strong>${people}<small>명</small></strong><small>전체 참여 ${full}명 · 부분 참여 ${people-full}명</small></div><div class="card stat"><div class="stat-head">여행 일정 <span class="stat-icon">▦</span></div><strong>${d.events.length}<small>건</small></strong><small>예정 / 후보 일정 합계</small></div><div class="card stat"><div class="stat-head">가격 추적 중 <span class="stat-icon">↗</span></div><strong>${d.watches.filter(w=>w.is_active).length}<small>개</small></strong><small>항공 · 숙소 가격 비교</small></div><div class="card stat"><div class="stat-head">등록 경비 <span class="stat-icon">₩</span></div><strong>${expSum>=1000000?(expSum/10000).toLocaleString('ko-KR',{maximumFractionDigits:1}):money(expSum)}${expSum>=1000000?'<small>만원</small>':''}</strong><small>실제 지출로 입력한 금액만</small></div></div>
<div class="grid-2"><div class="stack"><section class="card"><div class="card-head"><h3 class="card-title">📅 다가올 여행 일정</h3><button class="btn-ghost" data-view="itinerary">전체 일정 보기 →</button></div>${upcoming.length?`<div class="timeline-list">${upcoming.map(e=>`<div class="timeline-row"><div class="timeline-date">${dateUTC(e.date).getUTCDate()}<small>${monthName(e.date)}</small></div><div><div class="timeline-title">${E(e.title)}</div><div class="timeline-desc">${E(e.area||'장소 미정')} ${e.time?'· '+E(e.time):''}</div></div>${categoryPill(e.category)}</div>`).join('')}</div>`:empty('아직 일정이 없어요','첫 여행 일정을 추가해 보세요.')}</section><section class="card"><div class="card-head"><h3 class="card-title">👥 함께하는 멤버</h3><button class="btn-ghost" data-view="members">참여 날짜 관리 →</button></div><div class="roster-preview">${d.members.slice(0,8).map((m,i)=>`<div class="person-tile">${personAvatar(m,i)}<div style="min-width:0"><div class="name">${E(m.name)}</div><small>${E(dateRangeOf(m))} ${m.starts_on!==t.start_date||m.ends_on!==t.end_date?'· 부분':''}</small></div></div>`).join('')||'<div class="help">멤버를 추가하세요.</div>'}</div></section></div>
<div class="stack"><section class="card"><div class="card-head"><h3 class="card-title">📉 가격 모니터링</h3><button class="btn-ghost" data-view="prices">시세 추적 →</button></div>${d.watches.slice(0,4).map(w=>{let q=latestPrice(w),c=change(w);return `<div class="balance-row"><span class="stat-icon" style="flex:0 0 34px">${w.kind==='flight'?'✈':'⌂'}</span><div class="grow" style="min-width:0"><div style="font-size:12px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${E(w.label)}</div><div class="subtle">${w.target_price?'목표 '+money(w.target_price):'목표 미설정'}</div></div><div style="text-align:right"><strong>${q?money(q.price):'기록 없음'}</strong><div class="price-change ${c===null?'':c<0?'down':'up'}">${c===null?'':c===0?'변동 없음':(c<0?'▼ ':'▲ ')+money(Math.abs(c))}</div></div></div>`}).join('')||empty('모니터링 항목이 없어요','항공권이나 숙소 가격을 기록해 보세요.')}${alerts.length?`<div class="notice" style="margin-top:15px">🎯 목표 가격 이하에 도달한 항목이 ${alerts.length}개 있어요. 최신 기록 날짜를 확인하세요.</div>`:''}</section><section class="card"><div class="card-head"><h3 class="card-title">✳ 여행 준비 체크</h3><span class="pill">TEAM TODO</span></div><div class="notice">📍 출발 날짜가 다른 멤버는 <b>참여 멤버</b> 탭에서 도착일과 귀국일을 따로 지정하세요.<br/>💸 공동 경비의 숙박비는 날짜별 실제 숙박 인원으로 나눌 수 있어요.<br/>🔎 가격은 직접 기록하거나 API 연동 후 자동 점검할 수 있어요.</div><div style="margin-top:12px" class="actions">${button('일정 추가','addEvent','btn-light')}${button('가격 추적 추가','addWatch','btn-soft')}</div></section></div></div>`}
function empty(title,sub){return `<div class="empty"><div class="empty-icon">✺</div><strong>${title}</strong><span>${sub}</span></div>`}
function itinerary(){const d=getData(),days=maxDays(),events=[...d.events].sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`));if(!days.includes(state.day))state.day=days[0];const ed=events.filter(e=>e.date===state.day),members=present(state.day);return `${header('BUILD THE EXPERIENCE','여행 일정표','날짜별 계획을 모으고, 그날 함께하는 사람도 확인하세요.',button('+ 일정 추가','addEvent'))}<div class="calendar-strip">${days.map((day,i)=>`<button class="day-chip ${day===state.day?'active':''}" data-action="selectDay" data-id="${day}"><span>DAY ${pad(i+1)}</span><strong>${dateUTC(day).getUTCDate()}</strong><small>${monthName(day)}</small>${events.some(e=>e.date===day)?'<i class="dot"></i>':''}</button>`).join('')}</div><div class="days-layout"><section class="card"><div class="card-head"><div><div class="eyebrow">${monthName(state.day)} ${dayLabel(state.day)}</div><h3 class="card-title" style="margin-top:5px">${dateText(state.day)} · DAY ${days.indexOf(state.day)+1}</h3></div>${button('+ 이 날에 추가','addEvent','btn-soft btn-small')}</div>${ed.length?ed.map(e=>`<div class="schedule-item"><div class="schedule-marker"></div><div class="schedule-main"><div class="actions">${categoryPill(e.category)} <span class="subtle">${E(e.time||'시간 미정')} · ${E(e.area||'장소 미정')}</span> ${e.status==='booked'?'<span class="pill booked">예약 완료</span>':''}</div><h4>${E(e.title)}</h4><p>${E(e.note||'')}</p></div><div class="schedule-actions"><button class="btn-ghost" data-action="editEvent" data-id="${E(e.id)}">수정</button><button class="btn-ghost" data-action="deleteEvent" data-id="${E(e.id)}" style="color:#c07e6c">×</button></div></div>`).join(''):empty('이날은 자유 일정!','일정을 추가하거나 느긋하게 쉬어도 좋아요.')}<p class="help">화면의 일정과 예약 상태는 직접 입력한 계획 기준입니다.</p></section><aside class="stack"><div class="card"><div class="card-head"><h3 class="card-title">이 날 함께하는 사람</h3><span class="pill good">${members.length}명 참여</span></div>${members.map((m,i)=>`<div class="member-list-item">${personAvatar(m,i)}<div><b style="font-size:12px">${E(m.name)}</b><div class="sub">${dateRangeOf(m)}</div></div></div>`).join('')||'<p class="muted">이 날짜에 참여하는 멤버가 없어요.</p>'}</div><div class="card"><h3 class="card-title">하루 계획 팁</h3><p class="muted" style="font-size:12px">멤버들의 도착·귀국 날짜를 설정하면 일정별 참석 인원을 쉽게 확인할 수 있습니다. 일정 카테고리로 항공, 숙소, 맛집, 액티비티를 구분해 보세요.</p>${button('참여 일정 확인','gotoMembers','btn-light btn-small')}</div></aside></div>`}
function membersView(){const d=getData(),t=d.trip,days=maxDays();return `${header('WHO IS COMING','여행 멤버 관리','여행 기간이 서로 달라도 날짜별로 누가 있는지 확인할 수 있어요.',button('+ 멤버 추가','addMember'))}<div class="card" style="margin-bottom:18px"><div class="card-head"><h3 class="card-title">📍 참여 기간 타임라인</h3><span class="pill">${days.length}일 기준</span></div><div class="member-timeline"><div class="range-row header"><div class="range-name">MEMBER</div><div class="range-dots" style="--days:${days.length}">${days.map((x,i)=>`<span title="${x}">${i%3===0?dateUTC(x).getUTCDate():''}</span>`).join('')}</div><div class="range-count">체류 일수</div></div>${d.members.map((m,i)=>`<div class="range-row"><div class="range-name">${E(m.name)}<small>${i<6?'':(m.starts_on!==t.start_date||m.ends_on!==t.end_date?'부분 참여':'전체 참여')}</small></div><div class="range-dots" style="--days:${days.length}">${days.map(day=>`<span class="range-cell ${memberActive(m,day)?(m.starts_on!==t.start_date||m.ends_on!==t.end_date?'partial':'on'):''}" title="${day} ${memberActive(m,day)?'참여':'미참여'}"></span>`).join('')}</div><div class="range-count">${Math.max(0,diff(m.starts_on,m.ends_on)+1)}일</div></div>`).join('')}</div><div class="range-summary"><span>🟩 전체 기간 참여 &nbsp; 🟧 부분 일정 참여</span><span>등록 인원: <b>${d.members.length}명</b></span></div></div><div class="card"><div class="card-head"><h3 class="card-title">참가자 상세</h3><span class="card-sub">실제 이름과 비행 날짜를 입력하세요</span></div><div class="roster-preview">${d.members.map((m,i)=>`<div class="person-tile" style="justify-content:space-between">${personAvatar(m,i)}<div style="min-width:0;flex:1"><div class="name">${E(m.name)} ${m.role==='organizer'?'<span class="pill" style="padding:1px 6px">OWNER</span>':''}</div><small>${dateRangeOf(m)} · ${Math.max(0,diff(m.starts_on,m.ends_on))}박</small></div><button class="btn btn-light btn-small" data-action="editMember" data-id="${E(m.id)}">수정</button></div>`).join('')||empty('멤버 없음','첫 멤버를 추가하세요.')}</div></div>`}
function pricesView(){const d=getData(),filter=state.priceFilter,watches=d.watches.filter(w=>filter==='all'||w.kind===filter),alerts=d.watches.filter(w=>w.target_price&&latestPrice(w)?.price<=w.target_price);return `${header('WATCH & SAVE','항공권 · 숙소 가격 추적','직접 기록한 가격과 API를 통해 수집한 가격을 비교합니다.',button('+ 모니터링 항목','addWatch'))}<div class="notice ${state.mode==='demo'?'warn':''}" style="margin-bottom:16px">${state.mode==='demo'?'⚠️ 데모 화면의 금액은 전부 <b>가상 예시 데이터</b>입니다. 실제 판매 가격이 아닙니다.':'가격은 조회 시점, 인원, 항공편·객실 조건에 따라 달라집니다. 예약 직전 공급처에서 최종 금액을 확인하세요.'} ${state.mode==='shared'?'자동 조회는 관리자가 GitHub Actions와 Amadeus API를 연결한 경우에만 작동합니다.':''}</div><div class="stats" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="card stat"><div class="stat-head">항공 추적 <span class="stat-icon">✈</span></div><strong>${d.watches.filter(w=>w.kind==='flight').length}<small>개</small></strong></div><div class="card stat"><div class="stat-head">숙소 추적 <span class="stat-icon">⌂</span></div><strong>${d.watches.filter(w=>w.kind==='stay').length}<small>개</small></strong></div><div class="card stat"><div class="stat-head">목표가 도달 <span class="stat-icon">◎</span></div><strong>${alerts.length}<small>개</small></strong><small>최신 기록 기준</small></div></div><div class="filters"><button class="filter ${filter==='all'?'active':''}" data-action="filterPrices" data-id="all">전체 ${d.watches.length}</button><button class="filter ${filter==='flight'?'active':''}" data-action="filterPrices" data-id="flight">✈ 항공권</button><button class="filter ${filter==='stay'?'active':''}" data-action="filterPrices" data-id="stay">⌂ 숙소</button></div><div class="watch-list">${watches.map(watchCard).join('')}</div>${!watches.length?empty('추적할 항목이 없어요','항공권 또는 숙소를 추가해 주세요.'):''}<div class="notice" style="margin-top:18px">🔐 Google Flights·Booking.com 등의 화면을 무단 수집하지 않습니다. 가격은 수동 기록 또는 공식 Amadeus API(별도 계정·설정)를 통해서만 추가됩니다. API에 없는 저비용항공사·풀빌라 상품은 직접 비교해야 합니다.</div>`}
function splitExpense(exp,members){const amount=Math.max(0,Math.round(Number(exp.amount)||0)), ids=arr(exp.participant_ids).filter(id=>members.some(m=>m.id===id));const selected=members.filter(m=>!ids.length||ids.includes(m.id));const weights=new Map(members.map(m=>[m.id,0]));if(!selected.length)return weights;let list=[];
if(exp.split_rule==='nights'&&exp.from_date&&exp.to_date&&exp.from_date<exp.to_date){let nights=dates(exp.from_date,nextDate(exp.to_date,-1));for(const day of nights){const awake=selected.filter(m=>day>=m.starts_on&&day<m.ends_on);const targets=awake.length?awake:selected;for(const m of targets)weights.set(m.id,weights.get(m.id)+1/targets.length)}for(const m of selected)weights.set(m.id,weights.get(m.id)/nights.length)}
else{let chosen=exp.split_rule==='present'?selected.filter(m=>memberActive(m,exp.expense_date)):selected;if(!chosen.length)chosen=selected;for(const m of chosen)weights.set(m.id,1/chosen.length)}
// Integer KRW allocations; largest remainder preserves total exactly.
let provisional=members.map(m=>({id:m.id,raw:amount*weights.get(m.id),whole:Math.floor(amount*weights.get(m.id))}));let rem=amount-provisional.reduce((n,p)=>n+p.whole,0);provisional.sort((a,b)=>(b.raw-b.whole)-(a.raw-a.whole));for(let i=0;i<rem&&i<provisional.length;i++)provisional[i].whole++;
return new Map(provisional.map(p=>[p.id,p.whole]));}
function balances(){const d=getData(), balances=new Map(d.members.map(m=>[m.id,0]));for(const e of d.expenses){let shares=splitExpense(e,d.members);for(const [id,c] of shares)balances.set(id,(balances.get(id)||0)-c);if(e.payer_id&&balances.has(e.payer_id))balances.set(e.payer_id,balances.get(e.payer_id)+Number(e.amount))}return balances;}
function settlements(){const b=balances(),credit=[...b].filter(([k,v])=>v>0).map(([id,amount])=>({id,amount})).sort((a,b)=>b.amount-a.amount),debit=[...b].filter(([k,v])=>v<0).map(([id,amount])=>({id,amount:-amount})).sort((a,b)=>b.amount-a.amount),result=[];let i=0,j=0;while(i<debit.length&&j<credit.length){let s=Math.min(debit[i].amount,credit[j].amount);if(s>0)result.push({from:debit[i].id,to:credit[j].id,amount:s});debit[i].amount-=s;credit[j].amount-=s;if(debit[i].amount===0)i++;if(credit[j].amount===0)j++}return result;}
function expensesView(){const d=getData(),total=d.expenses.reduce((n,e)=>n+Number(e.amount),0),b=balances(),s=settlements();return `${header('SPLIT WITHOUT STRESS','여행 공동 경비','누가 결제했는지, 누가 얼마를 부담하는지 투명하게 관리해요.',button('+ 지출 추가','addExpense'))}<div class="stats" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="card stat"><div class="stat-head">총 등록 지출 <span class="stat-icon">₩</span></div><strong>${money(total)}</strong></div><div class="card stat"><div class="stat-head">등록된 지출 <span class="stat-icon">▤</span></div><strong>${d.expenses.length}<small>건</small></strong></div><div class="card stat"><div class="stat-head">예상 평균 부담 <span class="stat-icon">♧</span></div><strong>${money(d.members.length?total/d.members.length:0)}</strong><small>참고용 평균 · 실제 정산은 다름</small></div></div><div class="grid-2"><div class="stack"><section class="card"><div class="card-head"><h3 class="card-title">💳 지출 내역</h3><span class="card-sub">통화: KRW 기준</span></div>${d.expenses.length?`<div style="overflow-x:auto"><table class="expense-table"><thead><tr><th>내용</th><th>결제자</th><th>분담 방식</th><th>금액</th><th></th></tr></thead><tbody>${[...d.expenses].sort((a,b)=>String(b.expense_date).localeCompare(String(a.expense_date))).map(e=>`<tr><td><b>${E(e.title)}</b><div class="subtle">${dateText(e.expense_date)}</div></td><td>${E(getMember(e.payer_id)?.name||'미지정')}</td><td><span class="pill">${e.split_rule==='nights'?'숙박일 기준':e.split_rule==='present'?'당일 참가자':'지정 인원'}</span></td><td class="amount">${money(e.amount)}</td><td><button class="btn-ghost" data-action="editExpense" data-id="${E(e.id)}">수정</button></td></tr>`).join('')}</tbody></table></div>`:empty('등록된 지출이 없어요','숙소 예약금, 렌터카, 식비 등을 추가해 보세요.')}</section><section class="card"><h3 class="card-title">숙박비 분배 방식</h3><p class="muted" style="font-size:12px">숙소를 예약할 때 지출 방식에서 <b>숙박일 기준</b>을 선택하면, 매일 실제로 숙박하는 인원에게 그날의 숙박비를 균등 분배합니다. 각 멤버의 귀국일 당일은 숙박하지 않은 것으로 계산합니다.</p><div class="notice">예: 1박 40만 원, 첫날 4명이 숙박하면 각 10만 원 부담. 멤버가 합류한 날부터 분담 인원이 자동으로 바뀝니다.</div></section></div><div class="stack"><section class="card"><div class="card-head"><h3 class="card-title">⚖ 멤버별 정산 잔액</h3><span class="card-sub">받을 돈 + / 보낼 돈 −</span></div>${d.members.map((m,i)=>{let v=b.get(m.id)||0;return `<div class="balance-row">${personAvatar(m,i)}<div class="grow"><strong style="font-size:12px">${E(m.name)}</strong><div class="subtle">${dateRangeOf(m)}</div></div><b class="${v>=0?'positive':'negative'}">${v>0?'+':v<0?'−':''}${money(Math.abs(v))}</b></div>`}).join('')||empty('멤버를 추가하세요','정산 대상이 아직 없습니다.')}</section><section class="card"><div class="card-head"><h3 class="card-title">🔁 추천 송금 경로</h3><span class="card-sub">송금 횟수를 줄인 계산</span></div>${s.length?s.map(x=>`<div class="settlement"><b>${E(getMember(x.from)?.name||'?')}</b> → <b>${E(getMember(x.to)?.name||'?')}</b> <strong style="float:right;color:#178b75">${money(x.amount)}</strong></div>`).join(''):empty('정산할 금액이 없어요','지출을 등록하면 이곳에 계산됩니다.')}<p class="help">실제 송금 여부를 추적하는 기능은 아닙니다. 결제자와 참석 날짜를 정확히 입력해야 합니다.</p></section></div></div>`}
function settingsView(){const d=getData(),t=d.trip;return `${header('OUR BALI TRIP','여행 설정','이번 발리 여행의 날짜와 기본 정보를 관리하세요.')}<div class="settings-grid"><section class="card"><div class="card-head"><h3 class="card-title">✳ 여행 기본 설정</h3></div><form id="tripForm"><div class="form-grid"><div class="form-row wide"><label>여행 이름</label><input name="title" value="${attr(t.title)}" required maxlength="80" ${!isOwner()?'disabled':''}></div><div class="form-row"><label>전체 여행 시작일</label><input name="start_date" type="date" value="${attr(t.start_date)}" required ${!isOwner()?'disabled':''}></div><div class="form-row"><label>전체 여행 마지막 날</label><input name="end_date" type="date" value="${attr(t.end_date)}" required ${!isOwner()?'disabled':''}></div></div><p class="help">여기 날짜는 전체 일정의 범위입니다. 참가자별 날짜는 '참여 멤버'에서 따로 지정합니다.</p>${isOwner()?`<div style="margin-top:16px">${button('설정 저장','submitTrip','btn-primary')}</div>`:'<div class="notice">여행 이름과 기간은 생성한 사람만 바꿀 수 있습니다.</div>'}</form><hr class="small-separator"/><div class="card-head"><h3 class="card-title">데이터 보관</h3></div><p class="muted" style="font-size:12px">JSON 내보내기로 일정·멤버·가격 기록·경비를 백업할 수 있어요.</p><div class="actions">${button('↓ JSON 백업','exportJson','btn-light')}${state.mode==='demo'?button('↑ 백업 가져오기','importJson','btn-light'):''}</div><input type="file" id="importInput" accept="application/json" class="hidden"></section><div class="stack"><section class="card"><div class="card-head"><h3 class="card-title">🔗 공유와 동기화</h3><span class="pill ${state.mode==='demo'?'warning':'good'}">${state.mode==='demo'?'데모 · 기기별 저장':'실시간 공동 관리'}</span></div>${state.mode==='shared'?`<p class="muted" style="font-size:12px">등록된 아이디로 로그인하면 이번 발리 여행에 바로 연결됩니다. 일정·가격 기록·경비는 멤버들과 함께 관리합니다.</p>`:`<div class="notice warn">지금은 브라우저 단독 데모입니다. 다른 사람이 이 주소를 열어도 변경 사항은 서로 공유되지 않습니다.<br/>실제 공동 관리는 <b>config.js에 Supabase 연결 정보</b>를 넣고 SQL 설정을 실행해야 합니다.</div><p class="help">README.md에서 Supabase 및 GitHub Pages 설정을 확인하세요.</p>`}</section><section class="card"><div class="card-head"><h3 class="card-title">⚡ 자동 가격 점검</h3></div><p class="muted" style="font-size:12px">GitHub Actions가 Amadeus API에서 조건에 맞는 항공권·호텔 시세를 조회해 기록하도록 구성할 수 있습니다. 비밀키는 반드시 GitHub Secrets에 보관해야 합니다.</p><div class="notice">자동 점검이 성공한 가격만 기록됩니다. API에 없는 항공사·숙소, 조건이 다른 상품 또는 실시간 조회가 제한되는 상품은 수동 확인이 필요합니다.</div></section></div></div>`}
function render(){if(!state.ready)return;const main=$('#main'),map={dashboard,itinerary,members:membersView,prices:pricesView,expenses:expensesView,settings:settingsView};if(!getData().trip)return;main.innerHTML=map[state.view]?.()||dashboard();$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view));$('#breadcrumbCurrent').textContent=labels[state.view]||'OVERVIEW';$('#modeTag').textContent=state.mode==='demo'?'● 데모 모드':'● 팀 공유 중';$('#modeTag').classList.toggle('shared',state.mode==='shared');$('#profileText').textContent=state.mode==='shared'?(getData().members.find(m=>m.user_id===state.user?.id)?.name||state.loginId||localStorage.getItem('bali-login-id')||'MEMBER'):'GUEST';}
function goto(view){state.view=view;if(view==='itinerary'&&!state.day)state.day=getData().trip.start_date;render();window.scrollTo({top:0,behavior:'smooth'});$('#sidebar').classList.remove('open')}
function modal(title,subtitle,body,foot=''){const mount=$('#modalMount');mount.innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-header"><div><h2 id="modalTitle">${title}</h2><p>${subtitle||''}</p></div><button class="modal-close" data-action="closeModal" aria-label="닫기">×</button></div>${body}${foot}</div></div>`;document.body.classList.add('no-scroll');}
function closeModal(){const el=$('#modalMount');el.innerHTML='';document.body.classList.remove('no-scroll')}
function formFoot(edit,delAction,delId){return `<div class="modal-actions">${edit&&delAction?button('삭제',delAction,'btn-danger',delId):''}<button type="button" class="btn btn-light" data-action="closeModal">취소</button><button type="submit" class="btn btn-primary">${edit?'변경 저장':'추가하기'}</button></div>`}
const field=(label,name,value='',type='text',extra='')=>`<div class="form-row"><label for="f-${name}">${label}</label><input id="f-${name}" type="${type}" name="${name}" value="${attr(value)}" ${extra}/></div>`;
const select=(label,name,options,value)=>`<div class="form-row"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([k,l])=>`<option value="${attr(k)}" ${k===value?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
function memberForm(id){const d=getData(),t=d.trip,m=d.members.find(x=>x.id===id),form=`<form id="memberForm"><input type="hidden" name="id" value="${attr(id||'')}"><div class="form-grid">${field('이름 / 닉네임','name',m?.name||'','text','required maxlength="30"')}${select('참가 유형 (표시용)','part',[['full','전체 기간'],['partial','부분 참여']],m&&(m.starts_on!==t.start_date||m.ends_on!==t.end_date)?'partial':'full')}${field('도착 날짜 (발리 기준)','starts_on',m?.starts_on||t.start_date,'date','required')}${field('귀국 날짜 (발리 기준)','ends_on',m?.ends_on||t.end_date,'date','required')}</div><p class="help">귀국 날짜는 해당 날짜 활동에 참여할 수 있지만, 그날 밤 숙박비는 부담하지 않는 것으로 계산합니다.</p>${formFoot(!!m,m&&isOwner()&&m.role!=='organizer'?'deleteMember':'',id)}</form>`;modal(m?'멤버 수정':'멤버 추가','개인별 도착일과 귀국일을 설정합니다.',form)}
function eventForm(id){const d=getData(),e=d.events.find(x=>x.id===id),form=`<form id="eventForm"><input type="hidden" name="id" value="${attr(id||'')}"><div class="form-grid"><div class="form-row wide">${field('일정 이름','title',e?.title||'','text','required maxlength="100"')}</div>${field('날짜','date',e?.date||state.day||d.trip.start_date,'date','required')}${field('시간','time',e?.time||'','time')}${select('유형','category',Object.entries(cats),e?.category||'activity')}${field('지역 / 장소','area',e?.area||'','text','placeholder="예: 우붓"')}${select('상태','status',[['idea','계획 중'],['booked','예약 완료']],e?.status||'idea')}<div class="form-row wide"><label>메모 / 주소</label><textarea name="note" placeholder="준비물, 예약번호 없이 공유할 내용 등">${E(e?.note||'')}</textarea></div></div>${formFoot(!!e,'deleteEvent',id)}</form>`;modal(e?'일정 수정':'새 일정 추가','각자 보고 수정할 수 있는 공동 일정입니다.',form)}
function watchForm(id){const d=getData(),w=d.watches.find(x=>x.id===id),kind=w?.kind||state.priceFilter==='stay'?'stay':'flight';const form=`<form id="watchForm"><input type="hidden" name="id" value="${attr(id||'')}"><div class="form-grid">${select('분류','kind',[['flight','항공권'],['stay','숙소']],w?.kind||'flight')}<div class="form-row">${field('모니터링 이름','label',w?.label||'','text','required maxlength="100"')}</div>${field('공급처 / 사이트','provider',w?.provider||'','text','placeholder="예: 대한항공, 호텔 공식 홈페이지"')}<div class="form-row wide">${field('비교·예약 사이트 URL','url',w?.url||'','url','placeholder="https://..."')}</div><div class="flight-only form-row">${field('출발 공항 코드','origin',w?.origin||'ICN','text','maxlength="3" pattern="[a-zA-Z]{3}"')}</div><div class="flight-only form-row">${field('도착 공항 코드','dest',w?.dest||'DPS','text','maxlength="3" pattern="[a-zA-Z]{3}"')}</div><div class="flight-only form-row">${field('출국일','depart_on',w?.depart_on||d.trip.start_date,'date')}</div><div class="flight-only form-row">${field('귀국일 (왕복인 경우)','return_on',w?.return_on||d.trip.end_date,'date')}</div><div class="stay-only form-row">${field('체크인','checkin_on',w?.checkin_on||d.trip.start_date,'date')}</div><div class="stay-only form-row">${field('체크아웃','checkout_on',w?.checkout_on||nextDate(d.trip.start_date,3),'date')}</div><div class="stay-only form-row">${field('Amadeus 호텔 ID (선택)','amadeus_hotel_id',w?.amadeus_hotel_id||'','text','placeholder="예: ABCD1234" maxlength="30"')}</div>${field('성인 인원 (숙소는 객실당)','adults',w?.adults||1,'number','required min="1" max="9"')}<div class="stay-only form-row">${field('예약 객실 수','rooms',w?.rooms||1,'number','min="1" max="9"')}</div>${field('목표 금액 · 원 (선택)','target_price',w?.target_price||'','number','min="0" step="1"')}<div class="flight-only form-row"><label>항공편 조건</label><label class="checkbox-line"><input type="checkbox" name="nonstop" ${w?.nonstop===false?'':'checked'}> 직항만 검색</label></div><div class="form-row wide"><label>특이 사항</label><textarea name="note" placeholder="수하물 포함 여부, 객실 타입, 취소 조건 등">${E(w?.note||'')}</textarea></div><div class="form-row wide"><label class="checkbox-line"><input type="checkbox" name="is_active" ${w?.is_active===false?'':'checked'}> 자동 점검 대상으로 활성화</label></div></div><p class="help">자동 검색: 항공은 공항·날짜·인원 조건, 숙소는 호텔 ID·날짜·인원·객실 수가 필요합니다. 호텔 ID가 없는 풀빌라는 수동 가격 기록만 가능합니다. 금액 단위는 KRW입니다.</p>${formFoot(!!w,'deleteWatch',id)}</form>`;modal(w?'시세 추적 수정':'가격 추적 시작','항공권·숙소를 같은 조건으로 반복 비교해요.',form);toggleWatchFields()}
function toggleWatchFields(){const v=$('#watchForm [name=kind]')?.value;$$('.flight-only').forEach(e=>e.classList.toggle('hidden',v!=='flight'));$$('.stay-only').forEach(e=>e.classList.toggle('hidden',v!=='stay'));}
function quoteForm(id){const w=getData().watches.find(x=>x.id===id);if(!w)return;const form=`<form id="quoteForm"><input type="hidden" name="watch_id" value="${attr(id)}"><div class="notice" style="margin-bottom:15px"><b>${E(w.label)}</b><br/>${w.kind==='flight'?'항공 검색 결과의 총 결제액(설정한 탑승 인원 기준)':'체크인~체크아웃 전체 숙박 총액(설정한 객실 수 기준)'}을 입력하세요.</div><div class="form-grid">${field('확인한 가격 (원)','price','','number','required min="1" step="1"')}${field('확인 날짜','observed_date',today(),'date','required')}${field('가격 출처','provider',w.provider||'직접 확인','text','required maxlength="80"')}<div class="form-row wide"><label>조건 메모 (수하물 / 식사 / 취소 정책 등)</label><textarea name="summary"></textarea></div></div>${formFoot(false)}</form>`;modal('가격 기록 추가','가격 변동 추이를 그래프로 확인할 수 있어요.',form)}
function expenseForm(id){const d=getData(),x=d.expenses.find(v=>v.id===id),form=`<form id="expenseForm"><input type="hidden" name="id" value="${attr(id||'')}"><div class="form-grid"><div class="form-row wide">${field('지출 항목','title',x?.title||'','text','required maxlength="100"')}</div>${field('금액 (원)','amount',x?.amount||'','number','required min="1" step="1"')}${field('결제 날짜','expense_date',x?.expense_date||d.trip.start_date,'date','required')}${select('결제자','payer_id',[['','결제자 선택'],...d.members.map(m=>[m.id,m.name])],x?.payer_id||'')}${select('분담 방식','split_rule',[['present','결제일 참여자끼리 나누기'],['nights','실제 숙박일 기준 나누기'],['custom','선택한 사람끼리 균등 분담']],x?.split_rule||'present')}<div class="nights-only form-row">${field('숙박 시작 (체크인)','from_date',x?.from_date||d.trip.start_date,'date')}</div><div class="nights-only form-row">${field('숙박 종료 (체크아웃)','to_date',x?.to_date||nextDate(d.trip.start_date,3),'date')}</div><div class="form-row wide"><label>분담 대상 (선택하지 않으면 전체 멤버를 대상으로 계산)</label><div class="chip-row">${d.members.map(m=>`<label class="checkbox-line chip"><input type="checkbox" name="participant_ids" value="${E(m.id)}" ${arr(x?.participant_ids).includes(m.id)?'checked':''}> ${E(m.name)}</label>`).join('')}</div></div><div class="form-row wide"><label>메모</label><textarea name="note">${E(x?.note||'')}</textarea></div></div><p class="help">숙박비는 체크인일부터 체크아웃 전날까지 매일 실제 숙박 인원으로 나누어 정산합니다.</p>${formFoot(!!x,'deleteExpense',id)}</form>`;modal(x?'공동 지출 수정':'공동 지출 추가','원화로 결제한 금액을 기준으로 정산합니다.',form);toggleExpenseFields()}
function toggleExpenseFields(){const nights=$('#expenseForm [name=split_rule]')?.value==='nights';$$('.nights-only').forEach(e=>e.classList.toggle('hidden',!nights));}
async function saveRecord(name,record){try{if(state.mode==='demo'){const collection=state.data[name];const at=collection.findIndex(x=>x.id===record.id);if(at>=0)collection[at]={...collection[at],...record};else collection.push({...record,id:record.id||uid(),trip_id:state.tripId});localSave();render();notify('저장했습니다. (현재 브라우저에만 저장)');return true}
const q=record.id?api.from(tableName(name)).update(record).eq('id',record.id).eq('trip_id',state.tripId):api.from(tableName(name)).insert({...record,trip_id:state.tripId});const {error}=await q;if(error)throw error;await loadCloudTrip(state.tripId,true);notify('팀 전체에 저장되었습니다.');return true}catch(e){console.error(e);notify('저장 실패: '+e.message);return false}}
const tableName=s=>({members:'trip_members',events:'trip_events',watches:'watch_items',quotes:'price_quotes',expenses:'trip_expenses'}[s]);
async function removeRecord(name,id){if(!window.confirm('정말 삭제할까요? 다른 멤버에게도 반영됩니다.'))return false;try{if(state.mode==='demo'){state.data[name]=state.data[name].filter(v=>v.id!==id);if(name==='watches')state.data.quotes=state.data.quotes.filter(v=>v.watch_id!==id);localSave();render();notify('삭제되었습니다.');return true}
const {error}=await api.from(tableName(name)).delete().eq('id',id).eq('trip_id',state.tripId);if(error)throw error;await loadCloudTrip(state.tripId,true);notify('삭제되었습니다.');return true}catch(e){notify('삭제 실패: '+e.message);return false}}
function localSave(){try{localStorage.setItem(STORAGE,JSON.stringify(state.data))}catch(e){console.warn(e)}}
function loadDemo(){try{const json=JSON.parse(localStorage.getItem(STORAGE)||'null');if(json&&json.trip&&Array.isArray(json.members)&&Array.isArray(json.events)&&Array.isArray(json.watches)&&Array.isArray(json.quotes)&&Array.isArray(json.expenses))return json}catch(e){}return sampleData()}
async function saveTrip(values){try{if(state.mode==='demo'){Object.assign(state.data.trip,values);localSave();render();notify('여행 설정을 저장했습니다.');return}
const {error}=await api.from('trips').update(values).eq('id',state.tripId);if(error)throw error;await loadCloudTrip(state.tripId,true);notify('여행 설정을 저장했습니다.')}catch(e){notify('변경 실패: '+e.message)}}
async function loadCloudTrip(id,quiet=false){if(!id)return;try{const [t,m,e,w,q,x]=await Promise.all([api.from('trips').select('*').eq('id',id).single(),api.from('trip_members').select('*').eq('trip_id',id).order('created_at'),api.from('trip_events').select('*').eq('trip_id',id).order('date'),api.from('watch_items').select('*').eq('trip_id',id).order('created_at'),api.from('price_quotes').select('*').eq('trip_id',id).order('observed_at'),api.from('trip_expenses').select('*').eq('trip_id',id).order('expense_date')]);for(const a of [t,m,e,w,q,x])if(a.error)throw a.error;
state.tripId=id;state.data={trip:t.data,members:m.data||[],events:e.data||[],watches:w.data||[],quotes:q.data||[],expenses:x.data||[]};state.ready=true;localStorage.setItem(TRIP_STORAGE,id);if(!quiet){goto('dashboard');subscribeCloud(id)}else render();}catch(err){console.error(err);notify('공유 여행 불러오기 오류: '+err.message);if(!quiet)showTripError('여행을 불러오지 못했습니다.',err.message)}}
function subscribeCloud(id){if(!api)return;if(state.channel)api.removeChannel(state.channel);let reloading=false;const reload=async()=>{if(reloading)return;reloading=true;try{await loadCloudTrip(id,true)}finally{reloading=false}};let channel=api.channel('crew-'+id);for(const table of ['trips','trip_members','trip_events','watch_items','price_quotes','trip_expenses'])channel=channel.on('postgres_changes',{event:'*',schema:'public',table,filter:table==='trips'?`id=eq.${id}`:`trip_id=eq.${id}`},reload);state.channel=channel.subscribe()}
function authPage(){state.ready=false;$('#main').innerHTML=`<div class="auth-screen"><div class="card auth-card"><div class="landing-crest">✺ BALI TOGETHER</div><div class="auth-icon">◈</div><h1>친구들과 떠날 준비됐나요?</h1><p>미리 등록한 아이디와 비밀번호로 들어오세요.<br/>여행 일정과 경비는 참여한 멤버끼리 공유됩니다.</p><form id="authForm"><div class="form-grid"><div class="form-row wide"><label>아이디</label><input type="text" name="username" required autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="예: 성호 또는 bali01" value="${attr(state.loginId)}"/></div><div class="form-row wide"><label>비밀번호</label><input type="password" name="password" required autocomplete="current-password" /></div><div class="form-row wide"><button type="submit" class="btn btn-primary">로그인 →</button></div></div></form><p class="help">여행 관리자가 미리 만든 계정으로만 로그인하세요. 계정이나 비밀번호는 관리자에게 문의하세요.</p></div></div>`;}
async function openBaliTrip(){if(!state.user)return authPage();state.ready=false;state.tripId=null;state.data=null;const {data:trips,error}=await api.from('trips').select('id').limit(2);if(error){showTripError('여행을 불러오지 못했습니다.',error.message);return}if(!trips?.length){showTripError('발리 여행 연결을 준비하고 있습니다.','관리자에게 여행 데이터 연결을 확인해 달라고 요청해 주세요.');return}if(trips.length!==1){showTripError('여행 연결을 확인해 주세요.','이 사이트는 이번 발리 여행 한 개만 사용합니다.');return}await loadCloudTrip(trips[0].id)}
function showTripError(title,detail){state.ready=false;$('#main').innerHTML=`<section class="card"><h2>${E(title)}</h2><p>${E(detail)}</p><div class="actions">${button('다시 시도','retryTrip','btn-light')}${button('로그아웃','logout','btn-light')}</div></section>`;}

function loginAddress(username){return window.BaliLogin.address(username)}
async function login(username,password){const submit=$('#authForm button[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;try{state.loginId=username;const email=await loginAddress(username);const {error}=await api.auth.signInWithPassword({email,password});if(error)throw error;localStorage.setItem('bali-login-id',username);notify('로그인했습니다.')}catch(e){notify('로그인 실패: '+(e.code==='invalid_credentials'?'아이디 또는 비밀번호를 확인해 주세요.':e.message))}finally{if(submit)submit.disabled=false}}
async function signOut(){await api.auth.signOut();state.user=null;state.tripId=null;state.data=null;state.ready=false;authPage();notify('로그아웃했습니다.');}
function toJSON(){const str=JSON.stringify({format:'BALI_TOGETHER_1',exported_at:new Date().toISOString(),data:state.data},null,2),blob=new Blob([str],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bali-crew-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('JSON 파일을 저장했습니다.');}
async function importJSON(file){if(!file)return;try{if(file.size>4e6)throw new Error('4MB 미만 파일만 지원합니다.');const input=JSON.parse(await file.text()),d=input.data;if(!d||!d.trip||!Array.isArray(d.members)||!Array.isArray(d.events)||!Array.isArray(d.watches)||!Array.isArray(d.quotes)||!Array.isArray(d.expenses))throw new Error('올바른 백업 파일이 아닙니다.');if(!confirm('현재 데모 데이터를 백업 파일 내용으로 교체할까요?'))return;state.data=d;state.tripId=d.trip.id;state.day=d.trip.start_date;localSave();goto('dashboard');notify('백업 데이터를 불러왔습니다.')}catch(e){notify('가져오기 오류: '+e.message)}}
async function submitForm(f){const fd=new FormData(f),get=k=>trim(fd.get(k)),id=get('id'),tripId=state.tripId;
try{
if(f.getAttribute('id')==='authForm'){await login(get('username'),String(fd.get('password')||''));return}
if(f.getAttribute('id')==='tripForm'){const a=get('start_date'),b=get('end_date');if(a>b)throw new Error('종료일이 시작일보다 빠릅니다.');if(diff(a,b)>92)throw new Error('현재 일정 화면은 최대 93일을 지원합니다.');await saveTrip({title:get('title'),start_date:a,end_date:b});return}
if(f.getAttribute('id')==='memberForm'){const a=get('starts_on'),b=get('ends_on'),t=getData().trip;if(a>b||a<t.start_date||b>t.end_date)throw new Error('참여 날짜는 전체 여행 범위 안에서 설정하세요.');const existing=getData().members.find(m=>m.id===id),record={name:get('name'),starts_on:a,ends_on:b};if(id)record.id=id;else Object.assign(record,{role:'member',user_id:null});const saved=await saveRecord('members',record);if(saved)closeModal();return}
if(f.getAttribute('id')==='eventForm'){if(!inTrip(get('date')))throw new Error('일정 날짜가 전체 여행 기간 밖입니다.');const record={date:get('date'),time:get('time'),title:get('title'),category:get('category'),area:get('area'),note:get('note'),status:get('status')};if(id)record.id=id;const saved=await saveRecord('events',record);if(saved){closeModal();state.day=record.date;render()}return}
if(f.getAttribute('id')==='watchForm'){const kind=get('kind');let record={kind,label:get('label'),provider:get('provider'),url:get('url'),target_price:Number(get('target_price'))||null,adults:Number(get('adults'))||1,rooms:Number(get('rooms'))||1,note:get('note'),currency:'KRW',is_active:fd.has('is_active'),origin:null,dest:null,depart_on:null,return_on:null,checkin_on:null,checkout_on:null,amadeus_hotel_id:null,nonstop:fd.has('nonstop')};if(record.url&&!safeUrl(record.url))throw new Error('URL은 http 또는 https로 시작해야 합니다.');if(kind==='flight'){record.origin=get('origin').toUpperCase();record.dest=get('dest').toUpperCase();record.depart_on=get('depart_on');record.return_on=get('return_on')||null;if(!/^[A-Z]{3}$/.test(record.origin+'' )||!/^[A-Z]{3}$/.test(record.dest))throw new Error('공항 코드는 3자리 영문이어야 합니다.');if(record.return_on&&record.return_on<record.depart_on)throw new Error('귀국일이 출국일보다 빠릅니다.');}
else{record.checkin_on=get('checkin_on');record.checkout_on=get('checkout_on');record.amadeus_hotel_id=get('amadeus_hotel_id').toUpperCase()||null;if(record.checkout_on<=record.checkin_on)throw new Error('체크아웃은 체크인보다 나중이어야 합니다.');}
if(id)record.id=id;const saved=await saveRecord('watches',record);if(saved)closeModal();return}
if(f.getAttribute('id')==='quoteForm'){const price=Number(get('price'));if(!Number.isSafeInteger(price)||price<=0)throw new Error('올바른 가격을 입력하세요.');const record={watch_id:get('watch_id'),price,currency:'KRW',observed_at:get('observed_date')+'T12:00:00Z',provider:get('provider'),summary:get('summary')};const saved=await saveRecord('quotes',record);if(saved)closeModal();return}
if(f.getAttribute('id')==='expenseForm'){const amount=Number(get('amount'));if(!Number.isSafeInteger(amount)||amount<=0)throw new Error('금액은 양의 정수여야 합니다.');const rule=get('split_rule');const record={title:get('title'),amount,expense_date:get('expense_date'),payer_id:get('payer_id')||null,split_rule:rule,participant_ids:fd.getAll('participant_ids'),from_date:rule==='nights'?get('from_date'):null,to_date:rule==='nights'?get('to_date'):null,note:get('note')};if(!record.payer_id)throw new Error('결제자를 지정해야 정산이 가능합니다.');if(!inTrip(record.expense_date))throw new Error('결제일은 여행 범위 안으로 설정하세요.');if(rule==='nights'&&(!record.from_date||!record.to_date||record.to_date<=record.from_date||record.from_date<getData().trip.start_date||record.to_date>nextDate(getData().trip.end_date)))throw new Error('숙박 범위를 여행 기간 안으로 설정하세요.');if(id)record.id=id;const saved=await saveRecord('expenses',record);if(saved)closeModal();return}
}catch(e){console.error(e);notify('확인해 주세요: '+e.message)}}
async function handleAction(action,id,target){switch(action){case'closeModal':closeModal();break;case'addMember':memberForm();break;case'editMember':memberForm(id);break;case'deleteMember':if(await removeRecord('members',id))closeModal();break;case'addEvent':eventForm();break;case'editEvent':eventForm(id);break;case'deleteEvent':if(await removeRecord('events',id))closeModal();break;case'addWatch':watchForm();break;case'editWatch':watchForm(id);break;case'deleteWatch':if(await removeRecord('watches',id))closeModal();break;case'addQuote':quoteForm(id);break;case'deleteQuote':await removeRecord('quotes',id);break;case'addExpense':expenseForm();break;case'editExpense':expenseForm(id);break;case'deleteExpense':if(await removeRecord('expenses',id))closeModal();break;case'selectDay':state.day=id;render();break;case'gotoMembers':goto('members');break;case'filterPrices':state.priceFilter=id;render();break;case'toggleHistory':$(`#history-${id}`)?.classList.toggle('hidden');break;case'submitTrip':$('#tripForm')?.requestSubmit();break;case'exportJson':toJSON();break;case'importJson':$('#importInput')?.click();break;case'retryTrip':await openBaliTrip();break;case'logout':await signOut();break;}}
async function init(){document.addEventListener('click',async ev=>{const v=ev.target.closest('[data-view]');if(v){ev.preventDefault();if(state.ready)goto(v.dataset.view);return}const a=ev.target.closest('[data-action]');if(a){ev.preventDefault();await handleAction(a.dataset.action,a.dataset.id,a);return}if(ev.target.id==='modalBackdrop')closeModal()});document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')){e.preventDefault();await submitForm(e.target)}});document.addEventListener('change',e=>{if(e.target.name==='kind')toggleWatchFields();if(e.target.name==='split_rule')toggleExpenseFields();if(e.target.id==='importInput')importJSON(e.target.files?.[0])});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#profileBtn').addEventListener('click',()=>{if(state.mode==='shared')modal('계정',state.loginId||localStorage.getItem('bali-login-id')||'멤버',`<div class="actions">${button('로그아웃','logout','btn-danger')}</div>`);else goto('settings')});if(state.mode==='demo'){state.data=loadDemo();state.tripId=state.data.trip.id;state.day=state.data.trip.start_date;state.ready=true;render();return}if(location.hash.startsWith('#join='))history.replaceState(null,'',location.pathname+location.search);localStorage.removeItem('bali-pending-invite');if(!api){$('#main').innerHTML='<div class="card"><h2>공유 서버 연결에 실패했습니다.</h2><p>Supabase 라이브러리를 불러올 수 없습니다. 인터넷 연결과 config.js 값을 확인하세요.</p></div>';return}const {data:{session}}=await api.auth.getSession();state.user=session?.user||null;api.auth.onAuthStateChange(async(event,session)=>{const newId=session?.user?.id;if(newId===state.user?.id)return;state.user=session?.user||null;if(newId){setTimeout(()=>openBaliTrip(),0)}else authPage()});if(state.user)await openBaliTrip();else authPage()}
init().catch(err=>{console.error(err);$('#main').innerHTML=`<div class="card"><h2>페이지를 열 수 없습니다.</h2><p>${E(err.message)}</p><p>설정과 인터넷 연결을 확인하세요.</p></div>`});
})();
